// The only way the app renders an icon: <Icon name="search" />.
// Stroke, caps and sizes come from DESIGN.md (via icon-config.ts, generated by tokens.mjs),
// so changing the icon signature is one edit for the whole app.
import type { ComponentType } from 'react';
import { iconConfig } from './icon-config';
import { icons } from './registry';

export type IconName = keyof typeof icons;
export type IconSize = keyof typeof iconConfig.sizes;

type Props = {
  name: IconName;
  size?: IconSize;
  /** Accessible name. Omit for decorative icons next to visible text. */
  label?: string;
  className?: string;
};

// Phosphor weights expressed as stroke width at 24px, so custom icons can match them.
const PHOSPHOR_STROKE = { thin: 0.75, light: 1.125, regular: 1.5, bold: 2.25, fill: 1.5, duotone: 1.5 } as const;

const library: string = iconConfig.library;
const phosphorWeight = iconConfig.weight as keyof typeof PHOSPHOR_STROKE;

export function Icon({ name, size = 'md', label, className }: Props) {
  const Glyph = icons[name] as ComponentType<any> & { custom?: boolean };
  const px = iconConfig.sizes[size];
  const a11y = label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true, focusable: 'false' };

  if (library === 'phosphor' && !Glyph.custom) {
    return <Glyph size={px} weight={phosphorWeight} className={className} {...a11y} />;
  }
  const base = library === 'phosphor' ? PHOSPHOR_STROKE[phosphorWeight] : iconConfig.stroke;
  return (
    <Glyph
      size={px}
      // keep the same visible stroke at every size
      strokeWidth={(base * 24) / px}
      strokeLinecap={iconConfig.cap}
      strokeLinejoin={iconConfig.join}
      className={className}
      {...a11y}
    />
  );
}
